/* 公共平台外壳与模块导航；各HTML独立维护业务布局。统一使用 Bootstrap 原生类。 */
(()=>{
 const page=document.body.dataset.page,s=Eam.s;
 const routes={'maintenance-acceptance':'保养验收','maintenance-task-list':'保养任务',workbench:'角色工作台',equipment:'设备台账','inspection-list':'点检任务','check-list':'专项检查','abnormal-events':'异常事件中心','defect-list':'缺陷台账','failure-events':'故障事件',hazards:'隐患协同','order-list':'维修工单',acceptance:'待验收','standard-list':'点检标准','route-list':'点检路线','plan-list':'点检计划','equipment-templates':'分类与参数模板','functional-locations':'功能位置管理','maintenance-plan-list':'保养计划',catalog:'原型范围'};
 document.getElementById('platform-header').innerHTML='<header class="navbar appbar sticky-top py-2 px-3"><div class="brand navbar-brand mb-0"><span class="badge bg-primary me-1">S</span>STECCN <small class="text-white-50">企业协同平台</small></div><div class="controls d-flex gap-2 align-items-center ms-auto"><button id="view-toggle" type="button" class="btn btn-outline-light btn-sm"></button><details class="review-controls"><summary class="btn btn-outline-light btn-sm">演示设置</summary><div class="review-panel dropdown-menu p-3"><div class="mb-2"><label class="form-label small">演示角色</label><select id="role" class="form-select form-select-sm" aria-label="演示角色"></select></div><div class="mb-2"><label class="form-label small">演示人员</label><select id="person" class="form-select form-select-sm" aria-label="演示人员"></select></div><div class="mb-2"><label class="form-label small">演示场景</label><select id="scenario" class="form-select form-select-sm" aria-label="演示场景"><option value="normal">正常场景</option><option value="empty">空数据</option><option value="forbidden">无模块权限</option><option value="stale">信号陈旧</option><option value="failure">提交失败</option><option value="conflict">版本冲突</option><option value="qualification">资格失效</option><option value="loading">读取中</option></select></div><button id="reset" class="btn btn-outline-secondary btn-sm">重置会话</button></div></details></div></header>';
 for(const r of EAM_DEMO.roles)document.getElementById('role').add(new Option(r[1],r[0],false,r[0]===s.role));
 for(const p of EamDomain.people.filter(p=>p.roles.includes(s.role)))document.getElementById('person').add(new Option(p.name+' · '+p.id,p.id,false,p.id===s.person));
 document.getElementById('role').onchange=e=>{s.role=e.target.value;const index=EAM_DEMO.roles.findIndex(r=>r[0]===s.role);s.person=EamDomain.people[index].id;Eam.save();location.reload();};
 document.getElementById('person').onchange=e=>{s.person=e.target.value;Eam.save();location.reload();};
 document.getElementById('scenario').value=s.scenario;
 document.getElementById('scenario').onchange=e=>{s.scenario=e.target.value;Eam.save();location.reload();};
 document.getElementById('reset').onclick=()=>{sessionStorage.removeItem(Eam.key);sessionStorage.removeItem('eam-problems-v1');location.href='platform.html'+location.search;};
 const aside=document.getElementById('module-nav');
 if(page==='platform')aside.hidden=true;
 else {
 const heading=document.createElement('h2');heading.className='module-heading';heading.textContent='设备管理';aside.append(heading);const navBody=document.createElement('div');navBody.className='module-nav-body';aside.append(navBody);
 const groups=[['工作入口',['workbench']],['设备资产',['equipment','functional-locations']],['日常维护',['inspection-list','check-list','maintenance-task-list','maintenance-acceptance']],['异常处置',['abnormal-events','defect-list','failure-events','hazards']],['维修闭环',['order-list','acceptance']],['基础配置',['maintenance-plan-list','equipment-templates','standard-list','route-list','plan-list']]];
 const shapes={'maintenance-acceptance':'M5 3h14v18H5z M8 12l3 3 5-6','maintenance-task-list':'M5 4h14v17H5z M8 10l2 2 5-5 M8 16h8','maintenance-plan-list':'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16 M8 14h8',workbench:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',equipment:'M4 7h16v14H4z M8 7V3h8v4 M8 12h8 M8 16h5','functional-locations':'M12 21s7-7 7-12a7 7 0 1 0-14 0c0 5 7 12 7 12z M10 9h4', 'inspection-list':'M5 4h14v17H5z M9 4V2h6v2 M8 10l2 2 5-5 M8 16h8','check-list':'M4 4h16v16H4z M8 8h8 M8 12h8 M8 16h5','abnormal-events':'M12 3 2 21h20L12 3z M12 9v5 M12 17v1','defect-list':'M4 4h16v16H4z M9 8l-2 4 4 2-1 4 M15 8v8','failure-events':'M13 2 4 14h7l-1 8 10-13h-8l1-7z',hazards:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6l-9-4z M12 7v6 M12 16v1','order-list':'M14 5a5 5 0 0 0-6 6L3 16l5 5 5-5a5 5 0 0 0 6-6l-4 3-4-4 3-4z',acceptance:'M5 3h14v18H5z M8 12l3 3 5-6','equipment-templates':'M3 3h8v8H3z M15 3h6v6h-6z M3 15h6v6H3z M13 13h8v8h-8z','standard-list':'M5 3h14v18H5z M8 7h8 M8 11h8 M8 15h5','route-list':'M5 5h14v7H5v7h14 M3 3h4v4H3z M17 17h4v4h-4z','plan-list':'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16 M8 14h3 M14 14h3'};
 const active=({'maintenance-task':'maintenance-task-list','maintenance-plan':'maintenance-plan-list',inspection:new URLSearchParams(location.search).get('tab')==='special'?'check-list':'inspection-list',defect:'defect-list',order:'order-list',standards:'standard-list',plans:'plan-list',device:'equipment','asset-files':'equipment',history:'equipment'}[page]||page);
 for(const [label,keys]of groups){const section=document.createElement('section');section.className='nav-group';const h=document.createElement('h3');h.textContent=label;section.append(h);for(const key of keys){const button=document.createElement('button');button.type='button';button.dataset.page=key;button.innerHTML='<svg class="nav-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="'+shapes[key]+'"/></svg><span>'+routes[key]+'</span>';button.classList.toggle('active',key===active);if(key===active)button.setAttribute('aria-current','page');section.append(button);}navBody.append(section);}
 // 只调整菜单自己的滚动位置，不滚动页面主内容。
 function revealActive(){const selected=navBody.querySelector('[aria-current=page]');if(!selected||navBody.clientHeight===0)return;const box=navBody.getBoundingClientRect(),row=selected.getBoundingClientRect();if(row.top<box.top+8||row.bottom>box.bottom-8)navBody.scrollTop=Math.max(0,navBody.scrollTop+row.top-box.top-(navBody.clientHeight-row.height)/2);}
 requestAnimationFrame(revealActive);new ResizeObserver(revealActive).observe(navBody);document.addEventListener('click',e=>{if(e.target.closest('#nav-toggle,#view-toggle'))requestAnimationFrame(revealActive);});
 const back=document.createElement('button');back.className='nav-platform';back.type='button';back.textContent='← 返回平台';back.dataset.page='platform';aside.append(back);
 }
 const scope=document.createElement('button');scope.type='button';scope.className='btn btn-outline-secondary btn-sm mt-2';scope.dataset.page='catalog';scope.textContent='原型范围';document.querySelector('.review-panel').append(scope);
 // 面包屑统一由 page-table-components.js 的 pageHeader() 基于 EamPageRoutes 重建，此处不再重复写入，避免双源漂移。
 let mobile=new URLSearchParams(location.search).get('view')==='mobile';document.body.classList.toggle('mobile-preview',mobile);const viewButton=document.getElementById('view-toggle');viewButton.textContent=mobile?'切换 PC 端':'切换移动端';viewButton.setAttribute('aria-pressed',String(mobile));viewButton.onclick=()=>{mobile=!mobile;document.body.classList.toggle('mobile-preview',mobile);viewButton.textContent=mobile?'切换 PC 端':'切换移动端';viewButton.setAttribute('aria-pressed',String(mobile));const url=new URL(location.href);url.searchParams.set('view',mobile?'mobile':'pc');history.replaceState(null,'',url);};
 if(page!=='platform'){const nav=document.createElement('nav');nav.className='mobile-nav';for(const [key,label]of [['workbench','工作台'],['inspection-list','任务'],['equipment','设备'],['abnormal-events','异常']]){const b=document.createElement('button');b.type='button';b.textContent=label;b.dataset.page=key;b.classList.toggle('active',key===({inspection:new URLSearchParams(location.search).get('tab')==='special'?'check-list':'inspection-list',defect:'defect-list',order:'order-list',standards:'standard-list',plans:'plan-list',device:'equipment'}[page]||page));nav.append(b);}document.getElementById('mobile-nav').append(nav);}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b&&b!==document.body)Eam.go(b.dataset.page,{}, {noContext:!!b.closest('#module-nav,#mobile-nav,.review-panel')});if(e.target.closest('[data-action="enter"]'))Eam.go('workbench');});
 const origin=new URLSearchParams(location.search).get('returnEquipment');if(origin&&page!=='device'){const context=document.createElement('p');context.className='small text-secondary d-flex flex-wrap align-items-center gap-2';context.dataset.component='equipment-context';const caption=document.createElement('span');caption.textContent='当前设备范围：'+origin;const link=document.createElement('a');link.textContent='查看设备档案';const back=EamArchiveContext.navigate('device',{},location.search,page);link.href='device.html?'+new URLSearchParams({...back,view:new URLSearchParams(location.search).get('view')||'pc'});context.append(caption,link);const main=document.querySelector('main');const title=main.querySelector(':scope>.title,:scope>.pagehead');if(title)title.after(context);else main.prepend(context);}
 if(!['platform','device'].includes(page)&&['empty','forbidden','loading'].includes(s.scenario)&&!(s.scenario!=='forbidden'&&['abnormal-events','defect-list','failure-events','hazards','order-list'].includes(page))){const main=document.querySelector('main');main.replaceChildren();const h=document.createElement('h1');h.textContent=({empty:'当前范围暂无数据',forbidden:'无设备管理访问权限',loading:'正在读取设备数据…'})[s.scenario];const p=document.createElement('p');p.textContent='评审场景；可切回正常场景继续。';const b=document.createElement('button');b.type='button';b.className='btn btn-primary';b.textContent='返回平台';b.dataset.page='platform';main.append(h,p,b);main.dataset.state=s.scenario;if(s.scenario==='loading')main.setAttribute('aria-busy','true');}
 if(['failure','conflict','qualification'].includes(s.scenario))Eam.message(({failure:'提交失败场景：操作不会保存',conflict:'版本冲突场景：请恢复正常并重新读取',qualification:'资格失效场景：开工阻断，班组长需重新安排'})[s.scenario]);
})();
